use std::{fs, path::Path};
use zc::store::{Selection, Store};

const SOURCE: &[u8] = b"mixed-port: 9000\nrule-providers:\n  local: {type: file, behavior: domain, path: assets/rules.yaml}\nrules:\n  - RULE-SET,local,DIRECT\n";
const META: &[u8] = b"{\"active\":\"home\",\"configs\":{\"home\":{\"url\":\"https://example.test/sub\",\"filename\":\"Home\",\"params\":{\"target\":\"clash\"},\"selections\":{\"Proxy\":\"A\"}}}}\n";
// Generated by the actual Zig zc config list bootstrap with SOURCE/META above,
// using an isolated temporary HOME and XDG_RUNTIME_DIR (no listeners).
const ZIG_HEAD: &str = "03450c1a00f2372e3040dc0eb023cdfd";
const ZIG_DIGEST: &str = "83d45e8bb26786bc1188c673d750fdce2a2a4d610f91e1c0a9c8fc81107e5bea";

fn fixture(root: &Path) {
    fs::create_dir_all(root.join("configs/assets")).unwrap();
    fs::write(root.join("configs/home.yaml"), SOURCE).unwrap();
    fs::write(
        root.join("configs/assets/rules.yaml"),
        b"payload:\n  - example.com\n",
    )
    .unwrap();
    fs::write(root.join("meta.json"), META).unwrap();
}

#[test]
fn legacy_takeover_matches_zig_metadata_assets_identity_and_selections_once() {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join(".config/zc");
    fixture(&root);
    let store = Store::open(&root).unwrap();
    let snapshot = store.load().unwrap();
    assert_eq!(snapshot.catalog.sequence, 1);
    let profile = &snapshot.catalog.profiles[0];
    assert_eq!(profile.key, "home");
    assert_eq!(profile.head, ZIG_HEAD);
    assert_eq!(profile.desired.generation, 1);
    assert_eq!(
        profile.desired.selections,
        vec![Selection {
            group: "Proxy".into(),
            proxy: "A".into()
        }]
    );
    assert_eq!(snapshot.catalog.active.unwrap().revision, ZIG_HEAD);
    let view = store.read_bundle("home", ZIG_HEAD).unwrap();
    assert_eq!(view.content_digest, ZIG_DIGEST);
    assert_eq!(
        view.metadata.url.as_deref(),
        Some("https://example.test/sub")
    );
    assert_eq!(view.metadata.filename.as_deref(), Some("Home"));
    assert_eq!(view.metadata.params[0].key, "target");
    assert_eq!(view.metadata.params[0].value, "clash");
    assert_eq!(view.bundle.source(), SOURCE);
    assert_eq!(
        view.bundle.resolve_local("assets/rules.yaml").unwrap(),
        b"payload:\n  - example.com\n"
    );
    fs::remove_dir_all(root.join("configs")).unwrap();
    fs::write(root.join("meta.json"), b"broken mirror").unwrap();
    assert_eq!(store.load().unwrap().token, snapshot.token);
    assert!(view.bundle.runtime_config().is_ok());
}

// Emitted by Zig 0.16.0 Authority.commit(compare_exchange_head) in a real
// std.testing.tmpDir, using the independently generated migration head above.
const ZIG_SCHEMA_ONE: &[u8] = b"{\"schema_version\":1,\"sequence\":1,\"profiles\":[{\"key\":\"home\",\"head\":\"03450c1a00f2372e3040dc0eb023cdfd\"}]}\n";
fn state_file(root: &Path, bytes: &[u8]) {
    zc::fsutil::SecureDir::open(root)
        .unwrap()
        .atomic_write("state-v2.json", bytes)
        .unwrap();
}

#[test]
fn schema_one_requires_exact_content_proof_before_publishing_any_revision() {
    for (authority, valid) in [
        (ZIG_SCHEMA_ONE.to_vec(), true),
        (
            b"{\"schema_version\":1,\"sequence\":1,\"profiles\":[]}\n".to_vec(),
            false,
        ),
        (
            String::from_utf8(ZIG_SCHEMA_ONE.to_vec())
                .unwrap()
                .replace(ZIG_HEAD, "00112233445566778899aabbccddeeff")
                .into_bytes(),
            false,
        ),
        (
            String::from_utf8(ZIG_SCHEMA_ONE.to_vec())
                .unwrap()
                .replace("\"sequence\":1", "\"sequence\":18446744073709551615")
                .into_bytes(),
            false,
        ),
    ] {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().join("state");
        fixture(&root);
        let store = Store::open(&root).unwrap();
        state_file(&root, &authority);
        if valid {
            let result = store.load().unwrap();
            assert_eq!(result.catalog.sequence, 2);
            assert_eq!(result.catalog.active.unwrap().revision, ZIG_HEAD);
        } else {
            assert!(store.load().is_err());
            assert_eq!(fs::read(root.join("state-v2.json")).unwrap(), authority);
            assert!(!root.join("profiles").exists());
        }
    }
}

#[test]
fn disk_only_and_explicit_empty_selections_keep_distinct_baselines() {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("state");
    fs::create_dir_all(root.join("configs")).unwrap();
    for key in ["disk", "empty", "absent"] {
        fs::write(
            root.join(format!("configs/{key}.yaml")),
            b"mixed-port: 9000\n",
        )
        .unwrap();
    }
    fs::write(
        root.join("meta.json"),
        b"{\"active\":null,\"configs\":{\"empty\":{\"selections\":{}},\"absent\":{}}}",
    )
    .unwrap();
    let store = Store::open(&root).unwrap();
    assert_eq!(store.get("empty").unwrap().desired.generation, 1);
    assert_eq!(store.get("absent").unwrap().desired.generation, 0);
    assert_eq!(store.get("disk").unwrap().desired.generation, 0);
    assert!(store.load().unwrap().catalog.active.is_none());
}

#[test]
fn every_legacy_item_is_validated_before_immutable_publication() {
    let malformed_plugin = "mixed-port: 9000\nproxies:\n  - {name: edge, type: ss, server: 127.0.0.1, port: 443, cipher: aes-128-gcm, password: secret, plugin: unsupported}\n";
    for invalid in [
        "mixed-port: [9000]\n",
        "mixed-port: 9000\nrules: [MATCH,unknown]\n",
        "mixed-port: 9000\nrule-providers:\n  absent: {type: file, behavior: domain, path: missing.yaml}\n",
        &malformed_plugin.replace("127.0.0.1", "''"),
        "mixed-port: 9000\nproxies:\n  - {name: DIRECT, type: direct}\n",
    ] {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().join("state");
        fixture(&root);
        fs::write(root.join("configs/z.yaml"), invalid).unwrap();
        let store = Store::open(&root).unwrap();
        assert!(store.load().is_err(), "accepted {invalid}");
        assert!(!root.join("profiles").exists());
        assert!(!root.join("state-v2.json").exists());
        assert_eq!(fs::read(root.join("meta.json")).unwrap(), META);
    }
}

#[test]
fn malformed_obfs_is_preserved_but_cannot_remain_active() {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("state");
    fixture(&root);
    let source = b"mixed-port: 9000\nproxies:\n  - {name: edge, type: ss, server: 127.0.0.1, port: 443, cipher: aes-128-gcm, password: secret, plugin: obfs, plugin-opts: {mode: tls, host: example.com}}\n";
    fs::write(root.join("configs/home.yaml"), source).unwrap();
    let store = Store::open(&root).unwrap();
    let snapshot = store.load().unwrap();
    assert!(snapshot.catalog.active.is_none());
    let p = &snapshot.catalog.profiles[0];
    assert_eq!(p.desired.generation, 1);
    let view = store.read_bundle(&p.key, &p.head).unwrap();
    assert_eq!(view.bundle.source(), source);
    assert!(!view.bundle.catalog_ready().unwrap());
    assert!(store.activate(&snapshot.token, Some("home")).is_err());
    assert_eq!(store.load().unwrap().token, snapshot.token);
    store.delete(&snapshot.token, "home", &p.head).unwrap();
}

#[test]
fn invalid_metadata_never_resets_or_partially_publishes_legacy_state() {
    for metadata in [
        "",
        "{}",
        "active: null\nconfigs: {}\n",
        r#"{"active":"missing","configs":{}}"#,
        r#"{"active":null,"configs":{"missing":{}}}"#,
        r#"{"active":null,"configs":{"home":{"selections":null}}}"#,
        r#"{"active":null,"configs":{"home":{"params":{"":"value"}}}}"#,
        r#"{"active":null,"configs":{"home":{},"home":{}}}"#,
        r#"{"active":null,"configs":{"home":{"unknown":true}}}"#,
        r#"{"active":null,"configs":{"home":{"selections":{"g":"A","g":"B"}}}}"#,
    ] {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().join("state");
        fixture(&root);
        fs::write(root.join("meta.json"), metadata).unwrap();
        let store = Store::open(&root).unwrap();
        state_file(&root, ZIG_SCHEMA_ONE);
        assert!(store.load().is_err(), "accepted {metadata}");
        assert!(!root.join("profiles").exists());
        assert_eq!(
            fs::read(root.join("state-v2.json")).unwrap(),
            ZIG_SCHEMA_ONE
        );
        assert_eq!(
            fs::read(root.join("meta.json")).unwrap(),
            metadata.as_bytes()
        );
    }
}

