#[test]
fn zig_legacy_keys_251_through_255_remain_readable_and_deletable() {
    use zc::store::{ActiveIdentity, Bundle, Catalog, Desired, Metadata, Profile, valid_key};
    // Independent values emitted by Zig RevisionStore.publishMigration for k * n.
    let golden = [
        (
            251,
            "6f4307b242cd105a9956b8723fdaa4e78ccada5f9ed4d0672fe6f9030591c24f",
            "f183940c6b20fdcc697b61144dc726b7",
            "7efd4afccb1c2fae1effaf9439af958c3788beddbbb55acfaac42b604bc3b2d1",
        ),
        (
            252,
            "65c46bdae46ef6584a97e7b958c2fb53d8587ee475862ac57c1ba0db8c5222d3",
            "23b7a0fac5f66ce9f7fb30dce93c57d4",
            "9da42c1b35aaa13747e568f1a54424e80dea940d70dacb3e8d094bab915daa29",
        ),
        (
            253,
            "edf901d853f82f86694cdb2ef87405e24ea038f8d28ef0168c70e913bf3cf955",
            "d0e18dd62ed3843c8d2f962642fa1319",
            "7ecad42125ff104093b3ee1177a8007602655c09f6049395bd658fb5d5caec1a",
        ),
        (
            254,
            "d51e11ba0da000ff61071373e886b9e94e356373daf35058f21de9c0fd7a9ce8",
            "c824f3d1f1b272a65898fd0a29615a49",
            "6684b6bd8d9771e7c20b494494c3c92ab71f7410b46b424f1c167a550d252384",
        ),
        (
            255,
            "58598fd118f7c264277c19e1ac4766873771160989d5f7b2a99b06e6bde028e2",
            "f5b9dcc37374449d8b5f04d8748a4eab",
            "f9d49f52e318d2136545acea43a6c3dfe819e28c124f43f7c42b1108e5ecf279",
        ),
    ];
    for (length, id, head, content_digest) in golden {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().join("state");
        let store = Store::open(&root).unwrap();
        let key = "k".repeat(length);
        assert!(!valid_key(&key));
        assert!(valid_key(&"k".repeat(250)));
        let bundle = Bundle::from_memory(b"mixed-port: 9000\n", None, Default::default()).unwrap();
        assert!(
            store
                .publish(
                    &store.load().unwrap().token,
                    &key,
                    None,
                    &bundle,
                    Metadata::default(),
                    false
                )
                .is_err()
        );
        assert!(!root.join("profiles").exists());
        let dir = zc::fsutil::SecureDir::open(&root).unwrap();
        let profile = dir
            .child("profiles", true)
            .unwrap()
            .child(id, true)
            .unwrap();
        profile
            .write_new(
                "identity.json",
                serde_json::to_string(
                    &serde_json::json!({"schema_version":1,"key":key,"storage_id":id}),
                )
                .unwrap()
                .as_bytes(),
            )
            .unwrap();
        let revision = profile
            .child("revisions", true)
            .unwrap()
            .child(head, true)
            .unwrap();
        revision.child("objects", true).unwrap();
        revision
            .write_new("source.yaml", b"mixed-port: 9000\n")
            .unwrap();
        revision.write_new("manifest.json", serde_json::to_string(&serde_json::json!({
            "schema_version":1,"key":key,"storage_id":id,"revision":head,"content_digest":content_digest,
            "metadata":{"url":null,"filename":null,"params":[]},"override":null,
            "source":{"size":17,"sha256":"1a0d9cbe3966156e2d2c94a3e7211e147097950cc2fa46fc496254348f9882ff"},
            "materialized_source":null,"aggregate_bytes":17,"local_assets":[],"remote_providers":[]
        })).unwrap().as_bytes()).unwrap();
        let catalog = Catalog {
            schema_version: 2,
            sequence: 7,
            active: Some(ActiveIdentity {
                key: key.clone(),
                revision: head.into(),
            }),
            profiles: vec![Profile {
                key: key.clone(),
                storage_id: id.into(),
                head: head.into(),
                desired: Desired::default(),
            }],
        };
        state_file(
            &root,
            format!("{}\n", serde_json::to_string(&catalog).unwrap()).as_bytes(),
        );
        dir.write_new("meta.json", b"broken legacy mirror").unwrap();
        assert_eq!(store.get(&key).unwrap().head, head);
        assert_eq!(
            store.read_bundle(&key, head).unwrap().content_digest,
            content_digest
        );
        store
            .delete(&store.load().unwrap().token, &key, head)
            .unwrap();
        assert!(store.list().unwrap().is_empty());
        assert!(store.load().unwrap().catalog.active.is_none());
    }
}

#[tokio::test]
async fn persisted_override_executes_once_before_capturing_replaced_assets() {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("state");
    fixture(&root);
    let source = b"mixed-port: 9000\nrule-providers:\n  missing: {type: file, behavior: domain, path: absent.yaml}\nrules: [\"RULE-SET,missing,DIRECT\"]\n";
    fs::write(root.join("configs/home.yaml"), source).unwrap();
    let counter = temp.path().join("counter");
    let script = temp.path().join("override.sh");
    fs::write(&script, format!("#!/bin/sh\nprintf 'executed\\n' >> '{}'\n[ \"$ZC_OVERRIDE_COMMAND\" = legacy-migration ] || exit 1\n[ \"$ZC_OVERRIDE_ARG_COUNT\" = 0 ] || exit 2\n[ -z \"$ZC_OVERRIDE_ARG_PORT\" ] || exit 3\nprintf 'mixed-port: 9001\\nrule-providers: {{}}\\nrules: [\"MATCH,DIRECT\"]\\n'\n", counter.display())).unwrap();
    fs::write(root.join("meta.json"), serde_json::to_vec(&serde_json::json!({"active":"home","configs":{"home":{"override_script":script,"params":{"port":"9999"}}}})).unwrap()).unwrap();
    let store = Store::open(&root).unwrap();
    let snapshot = store.load().unwrap();
    let p = &snapshot.catalog.profiles[0];
    let view = store.read_bundle(&p.key, &p.head).unwrap();
    assert_eq!(view.bundle.source(), source);
    assert_eq!(
        view.bundle.runtime_config().unwrap().document()["mixed-port"],
        9001
    );
    let frozen = view.frozen_override.unwrap();
    assert_eq!(frozen.command, "legacy-migration");
    assert!(frozen.args.is_empty());
    assert_eq!(view.metadata.params[0].value, "9999");
    assert_eq!(frozen.script_bytes, fs::read(&script).unwrap());
    assert_eq!(fs::read(&counter).unwrap(), b"executed\n");
    fs::remove_dir_all(root.join("configs")).unwrap();
    fs::remove_file(root.join("meta.json")).unwrap();
    fs::remove_file(script).unwrap();
    assert_eq!(store.load().unwrap().token, snapshot.token);
    assert_eq!(fs::read(&counter).unwrap(), b"executed\n");
}

#[test]
fn repeat_witness_rejects_noncooperative_source_or_metadata_edits() {
    for target in ["configs/home.yaml", "meta.json", "override.sh"] {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().join("state");
        fixture(&root);
        fs::write(root.join("configs/z.yaml"), b"mixed-port: 9000\n").unwrap();
        let script = root.join("override.sh");
        fs::write(
            &script,
            format!(
                "#!/bin/sh\nprintf 'changed' > '{}'\nprintf 'mixed-port: 9001\\n'\n",
                root.join(target).display()
            ),
        )
        .unwrap();
        fs::write(root.join("meta.json"), serde_json::to_vec(&serde_json::json!({"active":null,"configs":{"home":{},"z":{"override_script":script}}})).unwrap()).unwrap();
        let store = Store::open(&root).unwrap();
        assert!(store.load().is_err(), "accepted changed {target}");
        assert!(!root.join("profiles").exists());
        assert!(!root.join("state-v2.json").exists());
    }
}

#[test]
fn escaping_assets_symlink_metadata_and_special_files_fail_without_blocking() {
    use std::os::unix::fs::symlink;
    for target in [
        "meta.json",
        "configs/home.yaml",
        "configs/assets/rules.yaml",
        "configs",
    ] {
        for special in [false, true] {
            let temp = tempfile::tempdir().unwrap();
            let root = temp.path().join("state");
            fixture(&root);
            let path = root.join(target);
            if path.is_dir() {
                fs::remove_dir_all(&path).unwrap();
            } else {
                fs::remove_file(&path).unwrap();
            }
            if special {
                assert!(
                    std::process::Command::new("mkfifo")
                        .arg(&path)
                        .status()
                        .unwrap()
                        .success()
                );
            } else {
                let outside = temp.path().join("outside");
                fs::write(&outside, SOURCE).unwrap();
                symlink(&outside, &path).unwrap();
            }
            let store = Store::open(&root).unwrap();
            assert!(store.load().is_err());
            assert!(!root.join("profiles").exists());
            assert!(!root.join("state-v2.json").exists());
        }
    }
}

#[test]
fn takeover_freezes_cooperative_writers_and_does_not_overwrite_new_legacy_state() {
    use std::time::Duration;
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("state");
    let store = Store::open_with_timeout(&root, Duration::from_millis(30)).unwrap();
    let missing = store.load().unwrap();
    fixture(&root);
    let dir = zc::fsutil::SecureDir::open(&root).unwrap();
    let guard = dir
        .lock("legacy-cutover.lock", Duration::from_millis(30))
        .unwrap();
    assert!(store.load().is_err());
    assert!(!root.join("profiles").exists());
    drop(guard);
    let bundle =
        zc::store::Bundle::from_memory(b"mixed-port: 9000\n", None, Default::default()).unwrap();
    assert!(
        store
            .publish(
                &missing.token,
                "other",
                None,
                &bundle,
                Default::default(),
                true
            )
            .is_err()
    );
    assert!(!root.join("state-v2.json").exists());
    assert_eq!(store.load().unwrap().catalog.profiles[0].head, ZIG_HEAD);
}

