#[test]
fn concurrent_process_takeovers_commit_once() {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("state");
    fixture(&root);
    let spawn = || {
        std::process::Command::new(std::env::current_exe().unwrap())
            .args(["--exact", "takeover_child", "--nocapture"])
            .env("ZC_LEGACY_TEST_ROOT", &root)
            .env("HOME", temp.path())
            .spawn()
            .unwrap()
    };
    let mut a = spawn();
    let mut b = spawn();
    assert!(a.wait().unwrap().success());
    assert!(b.wait().unwrap().success());
    let store = Store::open(&root).unwrap();
    assert_eq!(store.load().unwrap().catalog.sequence, 1);
}

#[tokio::test]
async fn deferred_http_is_rejected_offline_but_unmanaged_runtime_fetch_remains_supported() {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("state");
    fixture(&root);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    let source = format!(
        "mixed-port: 9000\nrule-providers:\n  remote: {{type: http, behavior: domain, path: remote.yaml, url: 'http://{address}/rules'}}\nrules: ['RULE-SET,remote,REJECT','MATCH,DIRECT']\n"
    );
    fs::write(root.join("configs/home.yaml"), &source).unwrap();
    let store = Store::open(&root).unwrap();
    // Original legacy_catalog_bootstrap_test.zig:381 rejects this before writes.
    assert!(store.load().is_err());
    assert!(!root.join("state-v2.json").exists());
    assert!(!root.join("profiles").exists());
    let server = tokio::spawn(async move {
        let (mut socket, _) = listener.accept().await.unwrap();
        let mut request = [0; 4096];
        assert!(socket.read(&mut request).await.unwrap() > 0);
        let body = "payload: [blocked.example]\n";
        socket
            .write_all(
                format!(
                    "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                )
                .as_bytes(),
            )
            .await
            .unwrap();
    });
    let unmanaged = zc::store::Bundle::capture_for_runtime(root.join("configs/home.yaml")).unwrap();
    assert!(unmanaged.catalog_ready().is_err());
    assert!(unmanaged.runtime_config().is_err());
    let fetched = zc::config::fetch_http_assets(&source).await.unwrap();
    let config = unmanaged.runtime_config_with_assets(&fetched).unwrap();
    assert_eq!(config.rules_json()["rules"].as_array().unwrap().len(), 2);
    assert_eq!(
        config.rules_json()["rules"][0]["payload"],
        "blocked.example"
    );
    server.await.unwrap();
    assert!(store.load().is_err());
}

#[test]
fn invalid_late_orphan_identity_is_rejected_before_publishing_earlier_items() {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("state");
    fixture(&root);
    fs::write(root.join("configs/z.yaml"), b"mixed-port: 9000\n").unwrap();
    let store = Store::open(&root).unwrap();
    let profiles = zc::fsutil::SecureDir::open(&root)
        .unwrap()
        .child("profiles", true)
        .unwrap();
    profiles
        .write_new(&zc::store::storage_id("z"), b"not a profile directory")
        .unwrap();
    assert!(store.load().is_err());
    assert!(
        !root
            .join(format!("profiles/{}", zc::store::storage_id("home")))
            .exists()
    );
    assert!(!root.join("state-v2.json").exists());
}

#[test]
fn invalid_materialized_plugin_is_not_raw_recovery_data() {
    use std::os::unix::fs::PermissionsExt;
    for patch in [
        "proxies: [{name: edge, type: ss, server: example.com, port: 8388, cipher: aes-128-gcm, password: secret, plugin: obfs, plugin-opts: {mode: tls, host: example.com}}]\nrules: ['MATCH,edge']\n",
        "",
    ] {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().join("state");
        fs::create_dir_all(root.join("configs")).unwrap();
        let source = if patch.is_empty() {
            "mixed-port: 9000\nproxies: [{name: edge, type: ss, server: example.com, port: 8388, cipher: aes-128-gcm, password: secret, plugin: obfs, plugin-opts: {mode: tls, host: example.com}}]\nrules: ['MATCH,edge']\n"
        } else {
            "mixed-port: 9000\n"
        };
        fs::write(root.join("configs/home.yaml"), source).unwrap();
        let script = temp.path().join("override.sh");
        fs::write(&script, format!("#!/bin/sh\ncat <<'PATCH'\n{patch}PATCH\n")).unwrap();
        fs::set_permissions(&script, fs::Permissions::from_mode(0o700)).unwrap();
        fs::write(
            root.join("meta.json"),
            serde_json::to_vec(
                &serde_json::json!({"active":"home","configs":{"home":{"override_script":script}}}),
            )
            .unwrap(),
        )
        .unwrap();
        assert!(Store::open(&root).unwrap().load().is_err());
        assert!(!root.join("state-v2.json").exists());
        assert!(!root.join("profiles").exists());
    }
}

#[test]
fn actual_zig_override_head_and_same_path_schema_one_proof_are_preserved() {
    use std::os::unix::fs::PermissionsExt;
    use zc::store::{Bundle, FrozenOverride, Metadata};
    let temp = tempfile::tempdir().unwrap();
    let source = include_bytes!("fixtures/state_minimal_source.yaml");
    let effective = include_bytes!("fixtures/state_minimal_effective.yaml");
    let script_bytes = include_bytes!("fixtures/state_override.sh");
    let frozen = |path: String| FrozenOverride {
        script_name: "override.sh".into(),
        script_bytes: script_bytes.to_vec(),
        command: "legacy-migration".into(),
        config_path: Some(path),
        timeout_ms: 5000,
        args: vec![],
        patch_bytes: include_bytes!("fixtures/state_patch.yaml").to_vec(),
    };
    let bundle = Bundle::from_memory(source, Some(effective), Default::default()).unwrap();
    let oracle: serde_json::Value =
        serde_json::from_slice(include_bytes!("fixtures/state_minimal_manifest.json")).unwrap();
    let evidence = Store::open(temp.path().join("evidence")).unwrap();
    evidence
        .publish_frozen(
            &evidence.load().unwrap().token,
            "home",
            None,
            &bundle,
            Metadata::default(),
            Some(frozen(
                oracle["override"]["config_path"].as_str().unwrap().into(),
            )),
            true,
        )
        .unwrap();
    let p = evidence.get("home").unwrap();
    assert_eq!(p.head, "5109ae8cab8fed6a1f8b277cfd767d37");
    assert_eq!(
        evidence
            .read_bundle("home", &p.head)
            .unwrap()
            .content_digest,
        "49bd9dc5364a2ea3c235d6ac8ab3f4e4b32ad888885b5c7ce778a1ea8ac8bffa"
    );

    let root = temp.path().join("legacy");
    fs::create_dir_all(root.join("configs")).unwrap();
    fs::write(root.join("configs/home.yaml"), source).unwrap();
    let script = temp.path().join("override.sh");
    fs::write(&script, script_bytes).unwrap();
    fs::set_permissions(&script, fs::Permissions::from_mode(0o700)).unwrap();
    let meta = serde_json::to_vec(
        &serde_json::json!({"active":"home","configs":{"home":{"override_script":script}}}),
    )
    .unwrap();
    fs::write(root.join("meta.json"), &meta).unwrap();
    // Golden materialized bytes, not the implementation's materializer, seed
    // the proof at this machine's exact canonical invocation path.
    let expected_store = Store::open(temp.path().join("expected")).unwrap();
    expected_store
        .publish_frozen(
            &expected_store.load().unwrap().token,
            "home",
            None,
            &bundle,
            Metadata::default(),
            Some(frozen(
                root.join("configs/home.yaml")
                    .canonicalize()
                    .unwrap()
                    .to_str()
                    .unwrap()
                    .into(),
            )),
            true,
        )
        .unwrap();
    let head = expected_store.get("home").unwrap().head;
    let schema1 = serde_json::to_vec(&serde_json::json!({"schema_version":1,"sequence":7,"profiles":[{"key":"home","head":head}]})).unwrap();
    let store = Store::open(&root).unwrap();
    for _ in 0..2 {
        state_file(&root, &schema1);
        let snapshot = store.load().unwrap();
        assert_eq!(snapshot.catalog.sequence, 8);
        assert_eq!(snapshot.catalog.profiles[0].head, head);
        let view = store.read_bundle("home", &head).unwrap();
        assert_eq!(view.bundle.materialized().unwrap(), effective);
        assert!(view.bundle.runtime_config().is_ok());
    }
    state_file(&root, &schema1);
    fs::write(&script, b"#!/bin/sh\nprintf 'mixed-port: 9002\\n'\n").unwrap();
    assert!(
        store
            .load()
            .unwrap_err()
            .to_string()
            .contains("LegacyProofMismatch")
    );
    assert_eq!(fs::read(root.join("state-v2.json")).unwrap(), schema1);
}
